select * from `reimburse`


        AND reimburse_ID like concat('%',#{reimburse_ID},'%')


        AND apply_ID = #{apply_ID}


        AND teacher_ID = #{teacher_ID}


        AND money like concat('%',#{money},'%')


        AND status = #{status}


order by reimburse_ID desc

mapper.update:
update `reimburse`
set apply_ID = #{apply_ID}, teacher_ID = #{teacher_ID}, money = #{money},
    time = #{time}, status = #{status}
where reimburse_ID = #{reimburse_ID}
